export function getBackendUrl(): string {
  if (typeof window !== "undefined") {
    const saved = localStorage.getItem("durhack_backend_url");
    if (saved) return saved.trim();
    if (process.env.NEXT_PUBLIC_BACKEND_URL) {
      return process.env.NEXT_PUBLIC_BACKEND_URL.trim();
    }
    const hostname = window.location.hostname || "localhost";
    const protocol = window.location.protocol === "https:" ? "https:" : "http:";
    return `${protocol}//${hostname}:8000`;
  }
  return process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:8000";
}

export function getBackendWsUrl(): string {
  const httpUrl = getBackendUrl();
  return httpUrl.replace(/^http/, "ws");
}

export function setCustomBackendUrl(url: string) {
  if (typeof window !== "undefined") {
    if (!url) {
      localStorage.removeItem("durhack_backend_url");
    } else {
      localStorage.setItem("durhack_backend_url", url.trim());
    }
  }
}

import { getBackendUrl } from "./config";

export interface StreamPublisherConfig {
  streamId: string;
  clientName: string;
  facingMode: "user" | "environment";
  audioEnabled: boolean;
  videoEnabled: boolean;
  onConnectionStateChange?: (state: RTCPeerConnectionState) => void;
  onError?: (err: Error) => void;
}

export class WebRTCPublisher {
  private pc: RTCPeerConnection | null = null;
  private localStream: MediaStream | null = null;
  private config: StreamPublisherConfig;

  constructor(config: StreamPublisherConfig) {
    this.config = config;
  }

  public getStream(): MediaStream | null {
    return this.localStream;
  }

  public async start(): Promise<MediaStream> {
    const constraints: MediaStreamConstraints = {
      audio: this.config.audioEnabled ? {
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true,
      } : false,
      video: this.config.videoEnabled ? {
        facingMode: { ideal: this.config.facingMode },
        width: { ideal: 1280, max: 1920 },
        height: { ideal: 720, max: 1080 },
        frameRate: { ideal: 30, max: 60 },
      } : false,
    };

    try {
      this.localStream = await navigator.mediaDevices.getUserMedia(constraints);
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      this.config.onError?.(error);
      throw error;
    }

    this.pc = new RTCPeerConnection({
      iceServers: [
        { urls: "stun:stun.l.google.com:19302" },
        { urls: "stun:stun1.l.google.com:19302" },
      ],
    });

    this.pc.onconnectionstatechange = () => {
      if (this.pc) {
        this.config.onConnectionStateChange?.(this.pc.connectionState);
      }
    };

    // Add local tracks to peer connection
    this.localStream.getTracks().forEach((track) => {
      if (this.localStream && this.pc) {
        this.pc.addTrack(track, this.localStream);
      }
    });

    // Create SDP Offer
    const offer = await this.pc.createOffer({
      offerToReceiveAudio: false,
      offerToReceiveVideo: false,
    });
    await this.pc.setLocalDescription(offer);

    // Wait briefly for ICE candidates to gather
    await this.waitForIceGathering(this.pc);

    // Send offer to backend
    const backendUrl = getBackendUrl();
    const response = await fetch(`${backendUrl}/api/publish`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sdp: this.pc.localDescription?.sdp,
        type: this.pc.localDescription?.type,
        stream_id: this.config.streamId,
        client_name: this.config.clientName,
        device_info: {
          userAgent: navigator.userAgent,
          facingMode: this.config.facingMode,
        },
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Failed to publish stream: ${response.status} ${errorText}`);
    }

    const answer = await response.json();
    await this.pc.setRemoteDescription(new RTCSessionDescription(answer));

    return this.localStream;
  }

  public setAudioEnabled(enabled: boolean) {
    if (this.localStream) {
      this.localStream.getAudioTracks().forEach((track) => {
        track.enabled = enabled;
      });
    }
  }

  public setVideoEnabled(enabled: boolean) {
    if (this.localStream) {
      this.localStream.getVideoTracks().forEach((track) => {
        track.enabled = enabled;
      });
    }
  }

  public async switchCamera(newFacingMode: "user" | "environment") {
    this.config.facingMode = newFacingMode;
    if (!this.pc || !this.localStream) return;

    try {
      const newMediaStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: { exact: newFacingMode } },
        audio: false,
      });

      const newVideoTrack = newMediaStream.getVideoTracks()[0];
      const senders = this.pc.getSenders();
      const videoSender = senders.find((s) => s.track && s.track.kind === "video");

      if (videoSender && newVideoTrack) {
        await videoSender.replaceTrack(newVideoTrack);
        // Replace in local stream
        const oldVideoTrack = this.localStream.getVideoTracks()[0];
        if (oldVideoTrack) {
          this.localStream.removeTrack(oldVideoTrack);
          oldVideoTrack.stop();
        }
        this.localStream.addTrack(newVideoTrack);
      }
    } catch {
      // If exact facingMode fails, try ideal
      const fallbackStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: { ideal: newFacingMode } },
        audio: false,
      });
      const newVideoTrack = fallbackStream.getVideoTracks()[0];
      const senders = this.pc.getSenders();
      const videoSender = senders.find((s) => s.track && s.track.kind === "video");
      if (videoSender && newVideoTrack) {
        await videoSender.replaceTrack(newVideoTrack);
        const oldVideoTrack = this.localStream.getVideoTracks()[0];
        if (oldVideoTrack) {
          this.localStream.removeTrack(oldVideoTrack);
          oldVideoTrack.stop();
        }
        this.localStream.addTrack(newVideoTrack);
      }
    }
  }

  public stop() {
    if (this.localStream) {
      this.localStream.getTracks().forEach((track) => track.stop());
      this.localStream = null;
    }
    if (this.pc) {
      this.pc.close();
      this.pc = null;
    }
  }

  private waitForIceGathering(pc: RTCPeerConnection): Promise<void> {
    return new Promise((resolve) => {
      if (pc.iceGatheringState === "complete") {
        resolve();
        return;
      }
      const check = () => {
        if (pc.iceGatheringState === "complete") {
          pc.removeEventListener("icegatheringstatechange", check);
          resolve();
        }
      };
      pc.addEventListener("icegatheringstatechange", check);
      // Timeout fallback (800ms) to avoid blocking
      setTimeout(() => {
        pc.removeEventListener("icegatheringstatechange", check);
        resolve();
      }, 800);
    });
  }
}

export interface StreamViewerConfig {
  streamId: string;
  onTrack?: (stream: MediaStream) => void;
  onConnectionStateChange?: (state: RTCPeerConnectionState) => void;
  onError?: (err: Error) => void;
}

export class WebRTCViewer {
  private pc: RTCPeerConnection | null = null;
  private remoteStream: MediaStream = new MediaStream();
  private config: StreamViewerConfig;

  constructor(config: StreamViewerConfig) {
    this.config = config;
  }

  public async start(): Promise<MediaStream> {
    this.pc = new RTCPeerConnection({
      iceServers: [
        { urls: "stun:stun.l.google.com:19302" },
        { urls: "stun:stun1.l.google.com:19302" },
      ],
    });

    this.pc.onconnectionstatechange = () => {
      if (this.pc) {
        this.config.onConnectionStateChange?.(this.pc.connectionState);
      }
    };

    // Receive both video and audio
    this.pc.addTransceiver("video", { direction: "recvonly" });
    this.pc.addTransceiver("audio", { direction: "recvonly" });

    this.pc.ontrack = (event) => {
      if (event.streams && event.streams[0]) {
        this.remoteStream = event.streams[0];
      } else {
        this.remoteStream.addTrack(event.track);
      }
      this.config.onTrack?.(this.remoteStream);
    };

    const offer = await this.pc.createOffer();
    await this.pc.setLocalDescription(offer);

    // Wait briefly for ICE candidates
    await new Promise<void>((resolve) => {
      if (!this.pc || this.pc.iceGatheringState === "complete") {
        resolve();
        return;
      }
      const check = () => {
        if (this.pc?.iceGatheringState === "complete") {
          this.pc.removeEventListener("icegatheringstatechange", check);
          resolve();
        }
      };
      this.pc.addEventListener("icegatheringstatechange", check);
      setTimeout(() => {
        this.pc?.removeEventListener("icegatheringstatechange", check);
        resolve();
      }, 800);
    });

    const backendUrl = getBackendUrl();
    const response = await fetch(`${backendUrl}/api/view/${this.config.streamId}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sdp: this.pc.localDescription?.sdp,
        type: this.pc.localDescription?.type,
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Failed to view stream: ${response.status} ${errorText}`);
    }

    const answer = await response.json();
    await this.pc.setRemoteDescription(new RTCSessionDescription(answer));

    return this.remoteStream;
  }

  public stop() {
    if (this.pc) {
      this.pc.close();
      this.pc = null;
    }
    this.remoteStream.getTracks().forEach((track) => track.stop());
  }
}

"use client";

import React, { useEffect, useState } from "react";

interface AudioMeterProps {
  stream?: MediaStream | null;
  serverLevel?: number; // 0 to 100 level from backend websocket
  className?: string;
}

export const AudioMeter: React.FC<AudioMeterProps> = ({
  stream,
  serverLevel,
  className = "",
}) => {
  const [localLevel, setLocalLevel] = useState<number>(0);

  useEffect(() => {
    if (!stream || stream.getAudioTracks().length === 0) {
      setLocalLevel(0);
      return;
    }

    let audioContext: AudioContext | null = null;
    let analyser: AnalyserNode | null = null;
    let microphone: MediaStreamAudioSourceNode | null = null;
    let javascriptNode: ScriptProcessorNode | null = null;
    let isCancelled = false;

    try {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      audioContext = new AudioCtx();
      analyser = audioContext.createAnalyser();
      analyser.smoothingTimeConstant = 0.5;
      analyser.fftSize = 256;

      microphone = audioContext.createMediaStreamSource(stream);
      javascriptNode = audioContext.createScriptProcessor(512, 1, 1);

      microphone.connect(analyser);
      analyser.connect(javascriptNode);
      javascriptNode.connect(audioContext.destination);

      javascriptNode.onaudioprocess = () => {
        if (isCancelled) return;
        const array = new Uint8Array(analyser!.frequencyBinCount);
        analyser!.getByteFrequencyData(array);
        let values = 0;
        const length = array.length;
        for (let i = 0; i < length; i++) {
          values += array[i];
        }
        const average = values / length;
        const normalized = Math.min(100, Math.round((average / 128) * 100));
        setLocalLevel(normalized);
      };
    } catch {
      // AudioContext may be blocked before user interaction
    }

    return () => {
      isCancelled = true;
      if (javascriptNode) javascriptNode.onaudioprocess = null;
      if (microphone) microphone.disconnect();
      if (analyser) analyser.disconnect();
      if (javascriptNode) javascriptNode.disconnect();
      if (audioContext && audioContext.state !== "closed") {
        audioContext.close();
      }
    };
  }, [stream]);

  const level = serverLevel !== undefined ? serverLevel : localLevel;
  const bars = 6;
  const activeBars = Math.ceil((level / 100) * bars);

  return (
    <div className={`flex items-end gap-1 h-4 ${className}`} title={`Audio: ${level}%`}>
      {Array.from({ length: bars }).map((_, i) => {
        const isActive = i < activeBars;
        let color = "bg-emerald-500";
        if (i >= 4) color = "bg-amber-400";
        if (i >= 5) color = "bg-rose-500";

        return (
          <div
            key={i}
            className={`w-1 rounded-sm transition-all duration-75 ${
              isActive ? color : "bg-neutral-700/60"
            }`}
            style={{
              height: `${((i + 1) / bars) * 100}%`,
              opacity: isActive ? 1 : 0.35,
            }}
          />
        );
      })}
    </div>
  );
};

"use client";

import React, { useEffect, useRef, useState } from "react";
import {
  Volume2,
  VolumeX,
  Maximize2,
  Minimize2,
  Camera,
  XCircle,
  Activity,
  Radio,
} from "lucide-react";
import { WebRTCViewer } from "../lib/webrtc";
import { AudioMeter } from "./AudioMeter";
import { getBackendUrl } from "../lib/config";

export interface StreamItemData {
  stream_id: string;
  client_name: string;
  device_info?: {
    facingMode?: string;
    userAgent?: string;
  };
  has_video?: boolean;
  has_audio?: boolean;
  fps?: number;
  width?: number;
  height?: number;
  volume_level?: number;
  motion_score?: number;
}

interface StreamPlayerProps {
  stream: StreamItemData;
  onKick?: (streamId: string) => void;
  isSolo?: boolean;
  onToggleSolo?: (streamId: string) => void;
}

export const StreamPlayer: React.FC<StreamPlayerProps> = ({
  stream,
  onKick,
  isSolo = false,
  onToggleSolo,
}) => {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const viewerRef = useRef<WebRTCViewer | null>(null);

  const [connState, setConnState] = useState<RTCPeerConnectionState>("new");
  const [isMuted, setIsMuted] = useState<boolean>(true); // Default muted to allow autoplay without user gesture block
  const [isFullscreen, setIsFullscreen] = useState<boolean>(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [hasStartedPlaying, setHasStartedPlaying] = useState<boolean>(false);

  useEffect(() => {
    let viewer: WebRTCViewer | null = null;
    let isCancelled = false;

    async function initWebRTC() {
      try {
        setErrorMsg(null);
        viewer = new WebRTCViewer({
          streamId: stream.stream_id,
          onTrack: (remoteStream) => {
            if (isCancelled) return;
            if (videoRef.current) {
              videoRef.current.srcObject = remoteStream;
              videoRef.current
                .play()
                .then(() => setHasStartedPlaying(true))
                .catch(() => {
                  // User interaction might be required for unmuted playback
                  if (videoRef.current) {
                    videoRef.current.muted = true;
                    setIsMuted(true);
                    videoRef.current.play().then(() => setHasStartedPlaying(true));
                  }
                });
            }
          },
          onConnectionStateChange: (state) => {
            if (isCancelled) return;
            setConnState(state);
          },
          onError: (err) => {
            if (isCancelled) return;
            setErrorMsg(err.message);
          },
        });

        viewerRef.current = viewer;
        await viewer.start();
      } catch (err: unknown) {
        if (!isCancelled) {
          const message = err instanceof Error ? err.message : String(err);
          setErrorMsg(message);
        }
      }
    }

    initWebRTC();

    return () => {
      isCancelled = true;
      if (viewerRef.current) {
        viewerRef.current.stop();
        viewerRef.current = null;
      }
      if (videoRef.current) {
        videoRef.current.srcObject = null;
      }
    };
  }, [stream.stream_id]);

  const toggleMute = () => {
    if (videoRef.current) {
      const nextMuted = !isMuted;
      videoRef.current.muted = nextMuted;
      setIsMuted(nextMuted);
      if (!nextMuted) {
        videoRef.current.play().catch(console.error);
      }
    }
  };

  const toggleFullscreen = () => {
    if (!containerRef.current) return;
    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen().then(() => setIsFullscreen(true)).catch(console.error);
    } else {
      document.exitFullscreen().then(() => setIsFullscreen(false)).catch(console.error);
    }
  };

  const handleSnapshot = () => {
    const backendUrl = getBackendUrl();
    const snapshotUrl = `${backendUrl}/api/stream/${stream.stream_id}/snapshot.jpg?t=${Date.now()}`;
    window.open(snapshotUrl, "_blank");
  };

  return (
    <div
      ref={containerRef}
      className={`group relative flex flex-col bg-neutral-900 border border-neutral-800 rounded-2xl overflow-hidden shadow-xl transition-all duration-300 ${
        isSolo ? "ring-2 ring-emerald-500" : "hover:border-neutral-700"
      }`}
    >
      {/* Video Container */}
      <div className="relative aspect-video w-full bg-black flex items-center justify-center overflow-hidden">
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted={isMuted}
          className="w-full h-full object-contain"
        />

        {/* Loading / Disconnected state */}
        {(!hasStartedPlaying || connState !== "connected") && !errorMsg && (
          <div className="absolute inset-0 bg-neutral-950/80 backdrop-blur-xs flex flex-col items-center justify-center gap-3 text-neutral-400">
            <Radio className="w-8 h-8 animate-pulse text-indigo-400" />
            <span className="text-xs font-medium uppercase tracking-wider">
              {connState === "connecting" || connState === "new"
                ? "Connecting to phone..."
                : `Status: ${connState}`}
            </span>
          </div>
        )}

        {/* Error overlay */}
        {errorMsg && (
          <div className="absolute inset-0 bg-neutral-950/90 flex flex-col items-center justify-center p-4 text-center text-rose-400">
            <XCircle className="w-8 h-8 mb-2" />
            <p className="text-xs font-medium">{errorMsg}</p>
          </div>
        )}

        {/* Top Floating Badge Bar */}
        <div className="absolute top-3 left-3 right-3 flex items-center justify-between pointer-events-none">
          <div className="flex items-center gap-2 pointer-events-auto">
            <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-neutral-950/70 backdrop-blur-md text-white border border-white/10 shadow-sm">
              <span
                className={`w-2 h-2 rounded-full ${
                  connState === "connected"
                    ? "bg-emerald-500 animate-pulse"
                    : "bg-amber-400"
                }`}
              />
              {stream.client_name || "Camera"}
            </span>

            {stream.fps !== undefined && stream.fps > 0 && (
              <span className="hidden sm:inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-medium bg-neutral-950/60 backdrop-blur-md text-neutral-300 border border-white/5">
                <Activity className="w-3 h-3 text-cyan-400" />
                {stream.fps} FPS
              </span>
            )}
          </div>

          <div className="flex items-center gap-1.5 pointer-events-auto">
            {/* Audio level meter */}
            <div className="px-2 py-1 rounded-lg bg-neutral-950/70 backdrop-blur-md border border-white/10 flex items-center gap-1.5">
              <AudioMeter serverLevel={stream.volume_level} />
            </div>

            {/* Kick Button */}
            {onKick && (
              <button
                type="button"
                onClick={() => onKick(stream.stream_id)}
                className="p-1.5 rounded-lg bg-neutral-950/70 backdrop-blur-md text-neutral-400 hover:text-rose-400 hover:bg-rose-500/10 border border-white/10 transition-colors"
                title="Disconnect stream"
              >
                <XCircle className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>

        {/* Bottom Floating Control Bar (Fade on hover or mobile tap) */}
        <div className="absolute bottom-0 inset-x-0 p-3 bg-gradient-to-t from-black/80 via-black/40 to-transparent flex items-center justify-between opacity-90 sm:opacity-0 group-hover:opacity-100 transition-opacity">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={toggleMute}
              className={`p-2 rounded-xl backdrop-blur-md text-white transition-all ${
                isMuted
                  ? "bg-neutral-800/80 hover:bg-neutral-700/80 text-neutral-300"
                  : "bg-emerald-600/90 hover:bg-emerald-500/90 shadow-lg shadow-emerald-950"
              }`}
              title={isMuted ? "Unmute audio" : "Mute audio"}
            >
              {isMuted ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
            </button>

            {onToggleSolo && (
              <button
                type="button"
                onClick={() => onToggleSolo(stream.stream_id)}
                className={`px-2.5 py-1.5 rounded-xl text-xs font-semibold backdrop-blur-md transition-all ${
                  isSolo
                    ? "bg-emerald-600 text-white"
                    : "bg-neutral-800/80 hover:bg-neutral-700/80 text-neutral-300"
                }`}
                title="Solo this camera feed"
              >
                {isSolo ? "Solo Active" : "Solo"}
              </button>
            )}
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleSnapshot}
              className="p-2 rounded-xl bg-neutral-800/80 hover:bg-neutral-700/80 text-white backdrop-blur-md transition-colors"
              title="Capture full-res snapshot from server"
            >
              <Camera className="w-4 h-4" />
            </button>

            <button
              type="button"
              onClick={toggleFullscreen}
              className="p-2 rounded-xl bg-neutral-800/80 hover:bg-neutral-700/80 text-white backdrop-blur-md transition-colors"
              title="Toggle Fullscreen"
            >
              {isFullscreen ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
            </button>
          </div>
        </div>
      </div>

      {/* Stream Info Footer */}
